/**
 * A person who signs in to the app (epic: Shared Domain Entities → User).
 * `homeCurrency` is not part of F-1 — F-10 adds it.
 */
export interface User {
  /** UUID, generated by Postgres. */
  id: string;
  /** Trimmed and lower-cased before it is stored; unique. */
  email: string;
  /** Slow password hash (argon2id). Never leaves Identity. */
  passwordHash: string;
  createdAt: Date;
  updatedAt: Date;
}

/** What Identity needs to create a User; the id and timestamps are generated by Postgres. */
export interface NewUser {
  email: string;
  passwordHash: string;
}
